#include <cassert>
#include <cmath>
#include <iostream>
#include <stdexcept>
#ifdef NDEBUG
#error "Tests require assertions enabled."
#endif
struct Vec { double x,y; };
Vec rotateAround(Vec point,Vec pivot,double radians) {
    // 학습 범위를 명시한다. 물리 질량 중심이나 충돌은 계산하지 않는다.
    for(double v:{point.x,point.y,pivot.x,pivot.y})
        if(!std::isfinite(v) || std::fabs(v)>1000000.0) throw std::invalid_argument("position");
    if(!std::isfinite(radians) || std::fabs(radians)>1000.0) throw std::invalid_argument("angle");
    const double x=point.x-pivot.x,y=point.y-pivot.y;
    const double c=std::cos(radians),s=std::sin(radians);
    return Vec{pivot.x+c*x-s*y,pivot.y+s*x+c*y};
}
bool near(double a,double b) { return std::fabs(a-b)<1e-8; }
double distance2(Vec a,Vec b) { const double x=a.x-b.x,y=a.y-b.y;return x*x+y*y; }
int main() {
    const double pi=std::acos(-1.0);
    const Vec a=rotateAround({2,0},{0,0},pi/2);
    const Vec b=rotateAround({2,0},{1,0},pi/2);
    assert(near(a.x,0)&&near(a.y,2)); assert(near(b.x,1)&&near(b.y,1));
    const Vec fixed=rotateAround({3,4},{3,4},1.0);
    assert(near(fixed.x,3)&&near(fixed.y,4));
    for(int k=0;k<1000;++k) {
        const Vec p{(k%31)-15.0,(k%23)-11.0},o{1.0,-2.0};
        const double angle=k*0.01; const Vec q=rotateAround(p,o,angle);
        const Vec back=rotateAround(q,o,-angle);
        assert(near(back.x,p.x)&&near(back.y,p.y));
        assert(near(distance2(p,o),distance2(q,o)));
    }
    int rejected=0;
    try { rotateAround({std::nan(""),0},{0,0},0); } catch(const std::invalid_argument&) { ++rejected; }
    try { rotateAround({0,0},{0,0},1001); } catch(const std::invalid_argument&) { ++rejected; }
    assert(rejected==2);
    std::cout<<"pivot tests passed: 1000 inverse/distance cases\n";
}
